args.sparql:
SELECT DISTINCT ?mother ?motherLabel WHERE {
  { dbr:Prince_Alexander_of_the_Netherlands dbp:mother ?mother. }
  UNION
  { dbr:Prince_Alexander_of_the_Netherlands dbo:parent ?mother. }
  OPTIONAL { ?mother rdfs:label ?motherLabel FILTER (lang(?motherLabel) = "en") }
}

